// ============================================
// DOSYA 1: Dockerfile
// ============================================
// Multi-stage build ile production-ready Node.js image
//
// Stage 1 (builder):
//   - node:20-alpine base image
//   - WORKDIR /app
//   - package.json pnpm-lock.yaml kopyala → corepack enable && pnpm install --frozen-lockfile
//   - tsconfig.json ve src/ kopyala → pnpm build
//   - pnpm install --frozen-lockfile --prod (production deps ayrı)
//
// Stage 2 (production):
//   - node:20-alpine base image
//   - tini yükle (init process)
//   - WORKDIR /app
//   - builder'dan dist/, node_modules/, package.json kopyala
//   - USER node
//   - HEALTHCHECK ekle
//   - ENTRYPOINT ["tini", "--"]
//   - CMD ["node", "dist/server.js"]
//
// ============================================

// ============================================
// DOSYA 2: docker-compose.yml
// ============================================
// version: '3.8'
//
// services:
//   api:
//     build: .
//     ports: 3000:3000
//     environment: NODE_ENV, DATABASE_URL, REDIS_URL
//     depends_on: db (healthy), cache (started)
//     healthcheck: wget http://localhost:3000/health
//     restart: unless-stopped
//
//   db:
//     image: postgres:16-alpine
//     environment: POSTGRES_USER, POSTGRES_PASSWORD, POSTGRES_DB
//     volumes: postgres_data:/var/lib/postgresql/data
//     healthcheck: pg_isready
//     restart: unless-stopped
//
//   cache:
//     image: redis:7-alpine
//     command: redis-server --appendonly yes
//     volumes: redis_data:/data
//     healthcheck: redis-cli ping
//     restart: unless-stopped
//
// volumes:
//   postgres_data:
//   redis_data:
//
// ============================================

// ============================================
// DOSYA 3: .dockerignore
// ============================================
// node_modules, .git, .env, dist, coverage,
// Dockerfile, docker-compose*, .dockerignore,
// *.md, .vscode, .idea, __tests__
// ============================================

