// ============ Dockerfile ============

// # Stage 1: Builder
// FROM node:20-alpine AS builder
// WORKDIR /app
// COPY package.json pnpm-lock.yaml ./
// RUN corepack enable && pnpm install --frozen-lockfile
// COPY tsconfig.json ./
// COPY src/ ./src/
// RUN pnpm build
// RUN pnpm install --frozen-lockfile --prod && pnpm store prune
